yamlConstructors.put(null, new AbstractConstruct() {

    @Override
    public Object construct(final Node node) {
        if (!node.getTag().startsWith("!@")) {
            // Unknown tag - will fail
            return SafeConstructor.undefinedConstructor.construct(node);
        }
        // Unknown awareness - provide a graceful substitution
        return new PluginAwareness() {

            @Override
            public String toString() {
                return node.toString();
            }
        };
    }
})

Lists.transform(Arrays.asList(Server.class.getDeclaredMethods()), new Function<Method, Object[]>() {

    @Override
    public Object[] apply(Method input) {
        return new Object[] { input, input.toGenericString().substring("public abstract ".length()).replace("(", "{").replace(")", "}") };
    }
})
